(()=>{
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safe=value=>{try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}};
const color=c=>/^#[0-9a-f]{6}$/i.test(c.color)?c.color:'#5e7c62';
const notes=DATA.notes,noteMap=new Map(notes.map(n=>[n.id,n]));
const set=(id,text)=>document.getElementById(id).textContent=text;
set('weekly-title',DATA.title);set('weekly-subtitle',DATA.subtitle);set('weekly-intro',DATA.intro);
set('weekly-period','每週回望 / '+DATA.start+'—'+DATA.end+(DATA.inProgress?' / 截至 '+DATA.compiledAt:'')+(DATA.status==='draft'?' / 草稿預覽':''));
set('weekly-range',DATA.start+' — '+DATA.end);set('weekly-note-count',notes.length);set('weekly-topic-count',DATA.topicCount);set('weekly-video-count',DATA.videoCount);
set('weekly-method','整理範圍：'+DATA.start+'—'+DATA.end+'。依台灣時間建立日期歸週；無建立時間則採記事日期，同篇跨議題記事去重。依 '+DATA.compiledAt+' 已同步資料整理，後續記事編輯不會自動改寫本期內容。敘事、關係圖與延伸問題為 AI 輔助整理，引號保留原文；新聞與數字未另行查核。封面為共用概念插畫。');
const days=Array.from({length:7},(_,i)=>{const d=new Date(DATA.start+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+i);return d.toISOString().slice(0,10)}),counts=days.map(day=>notes.filter(n=>n.statDate===day).length),max=Math.max(1,...counts);
document.getElementById('days').innerHTML=counts.map((n,i)=>`<div class="day" aria-label="${esc(days[i])}，${n}篇記事"><b>${n}</b><i style="height:${n/max*78}px"></i><small>${esc(days[i].slice(5).replace('-','/'))}</small></div>`).join('');
const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true"><path d="M4 4h6v6H4ZM14 4h6v6h-6ZM9 15h6v6H9ZM7 10v3h10v-3M12 13v2"/></svg>';
document.getElementById('chapter-map').innerHTML=DATA.chapters.map(c=>`<a class="chapter-tile" href="#${esc(c.id)}" style="--c:${color(c)}"><span class="num">${esc(c.number)} / READING LINE</span><h3>${esc(c.name)}</h3><p>${esc(c.observation)}</p><small>${c.ids.length} 篇記事 · 點此閱讀</small></a>`).join('');
document.getElementById('weekly-toc').innerHTML='<p>本週閱讀路徑</p>'+DATA.chapters.map(c=>`<a href="#${esc(c.id)}"><span>${esc(c.number)}</span>${esc(c.name)}</a>`).join('')+(DATA.quote?'<a href="#my-voice">我的聲音</a>':'')+`<a href="#archive">${notes.length} 篇原始記事</a>`;
document.getElementById('chapters').innerHTML=DATA.chapters.map(c=>{const dates=c.ids.map(id=>noteMap.get(id).statDate).sort(),source=c.ids.map(id=>noteMap.get(id)).find(n=>n.links?.some(l=>safe(l.url))),link=source?.links.find(l=>safe(l.url));return `<section class="chapter" id="${esc(c.id)}" style="--c:${color(c)}"><div class="chapter-top"><span class="chapter-index">${esc(c.number)}</span><span class="chapter-tag">${esc(c.name)}</span><span class="chapter-date">${esc(dates[0])}—${esc(dates.at(-1))} · ${c.ids.length} 篇</span></div><h2>${esc(c.title)}</h2><p class="summary">${esc(c.summary)}</p><div class="observation"><small>整理後浮現的觀察</small>${esc(c.observation)}</div><div class="concept"><div class="concept-label">記事串起的關係 · 概念示意</div><div class="flow">${c.captions.map(text=>`<div class="flow-item"><span class="flow-icon">${icon}</span>${esc(text)}</div>`).join('')}</div></div><div class="next-question"><small>下次閱讀的問題</small><p>${esc(c.question)}</p></div><div class="chapter-source-row"><button class="text-button" data-filter-open="${esc(c.id)}">查看這 ${c.ids.length} 篇原記事 ↓</button>${link?`<a class="source-anchor" href="${esc(safe(link.url))}" target="_blank" rel="noopener noreferrer">觀看一段原始來源 ↗</a>`:''}</div></section>`}).join('');
if(DATA.quote){const n=noteMap.get(DATA.quote.noteId);document.getElementById('my-voice').hidden=false;set('weekly-quote','「'+DATA.quote.text+'」');document.getElementById('weekly-quote-source').innerHTML=esc(n.statDate)+' · <button class="text-button" data-note="'+esc(n.id)+'">讀原記事 ↗</button>'}
set('weekly-questions','');document.getElementById('weekly-questions').innerHTML=DATA.questions.map(q=>'<li>'+esc(q)+'</li>').join('');
let filter='all';const search=document.getElementById('archive-search');
function renderNotes(){const list=notes.filter(n=>(filter==='all'||n.chapter===filter)&&[n.title,n.text,...(n.topics||[]).map(t=>t.name)].join(' ').toLowerCase().includes(search.value.toLowerCase().trim()));document.getElementById('notes').innerHTML=list.map(n=>`<details class="note" id="note-${esc(n.id)}"><summary><time datetime="${esc(n.statDate)}">${esc(n.statDate.slice(5).replace('-','/'))}</time><b>${esc(n.title)}</b></summary><div class="note-meta">原議題：${(n.topics||[]).map(t=>esc(t.name)).join(' · ')}</div><div class="note-text">${esc(n.text)}</div><div class="note-sources">${(n.links||[]).filter(l=>safe(l.url)).map(l=>`<a href="${esc(safe(l.url))}" target="_blank" rel="noopener noreferrer">↗ ${esc(l.title)}</a>`).join('')||'<p>這篇記事沒有附上來源連結。</p>'}</div></details>`).join('');set('archive-count',`顯示 ${list.length} / ${notes.length} 篇原記事`);document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)})}
document.getElementById('filters').innerHTML=[{id:'all',name:'全部',count:notes.length},...DATA.chapters.map(c=>({id:c.id,name:c.name,count:c.ids.length}))].map(c=>`<button data-filter="${esc(c.id)}">${esc(c.name)} ${c.count}</button>`).join('');
function setFilter(value){filter=value;renderNotes()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));search.oninput=renderNotes;
document.querySelectorAll('[data-filter-open]').forEach(b=>b.onclick=()=>{search.value='';setFilter(b.dataset.filterOpen);document.getElementById('archive').scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{search.value='';setFilter('all');const el=document.getElementById('note-'+b.dataset.note);if(el){el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'})}});
window.addEventListener('scroll',()=>{const height=document.documentElement.scrollHeight-innerHeight;document.getElementById('reading-line').style.width=(height>0?scrollY/height*100:0)+'%'},{passive:true});
if(DATA.status==='draft'){document.querySelector('.report-actions').hidden=true;document.querySelector('.actions-row').hidden=true;document.querySelector('.brand').href='#top';document.querySelectorAll('a[href^="#"]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.getAttribute('href').slice(1))?.scrollIntoView({behavior:'smooth'})})}
renderNotes();
})();
